const prep = $('Prepare Data').first().json;

let inventory = [];
let hotbar = [];

try { inventory = JSON.parse(prep.inventoryJson || '[]'); } catch (e) {}
try { hotbar = JSON.parse(prep.hotbarJson || '[]'); } catch (e) {}

const userKey = prep.userId + '_' + prep.saveSlot;
const items = [];

inventory.forEach((item, idx) => {
  if (item && item.id) {
    items.push({
      json: {
        itemId: userKey + '_inv' + idx + '_' + item.id,
        userId: userKey,
        itemName: item.name || item.id,
        itemType: item.type || 'material',
        rarity: item.rarity || 'common',
        count: item.count || 1,
        weaponLevel: item.weaponLevel || 0,
        damage: item.damage || 0,
        slotType: 'inventory',
        slotIndex: idx,
        syncedAt: new Date(prep.timestamp).toISOString()
      }
    });
  }
});

hotbar.forEach((item, idx) => {
  if (item && item.id) {
    items.push({
      json: {
        itemId: userKey + '_hot' + idx + '_' + item.id,
        userId: userKey,
        itemName: item.name || item.id,
        itemType: item.type || 'weapon',
        rarity: item.rarity || 'common',
        count: item.count || 1,
        weaponLevel: item.weaponLevel || 0,
        damage: item.damage || 0,
        slotType: 'hotbar',
        slotIndex: idx,
        syncedAt: new Date(prep.timestamp).toISOString()
      }
    });
  }
});

return items;
